package generate

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/qrdl/regexped/config"
)

// The C stub for `wasm_format: component`.
//
// The HEADER is generated by the module-format code, unchanged: `cTypesPreamble`
// plus `genCPartsForEntry`'s `.h` half. That is deliberate — the header is the
// API, so sharing the generator makes the two formats API-identical by
// construction rather than by assertion.
//
// Only the `.c` differs, and C differs from Rust here. A Rust guest cannot
// declare its imports by hand, because `wasm32-wasip2` links the component in
// one step and demands component-type metadata. C builds a plain core module
// with clang, so the metadata can be attached AFTERWARDS by
// `wasm-tools component embed` — which means the C stub needs no binding
// generator and no third-party dependency at all. Verified end to end.
//
// Two things the module-format C stub does not need:
//
//   - the LOWERED import signature. A component import takes
//     `(ptr, len, start, retptr)` and returns void, with the CALLER supplying a
//     4-aligned return area; the result is read out of that area rather than
//     unpacked from an i64.
//   - `cabi_realloc`. A returned `list` is allocated in the CALLER's memory by
//     the composition glue, so a guest that receives one must export an
//     allocator. The groups shape returns one, and so do a set's `_all` pair
//     and its find's `next`, so it is emitted whenever any of them is present.

// cComponentStub writes the component-flavoured C stub, plus the WIT directory
// the build needs.
func cComponentStub(cfg config.BuildConfig, out string) error {
	hBase := "stub.h"
	if out != "-" {
		hBase = filepath.Base(strings.TrimSuffix(out, filepath.Ext(out)) + ".h")
	}
	hContent, cContent, err := genCComponentStubFiles(cfg, hBase)
	if err != nil {
		return fmt.Errorf("generate C component stub: %w", err)
	}
	if hContent == "" {
		return nil
	}
	hContent = applyNamespace(cfg, "c", hContent)
	cContent = applyNamespace(cfg, "c", cContent)
	if out == "-" {
		_, err := os.Stdout.WriteString(hContent + cContent)
		return err
	}
	base := strings.TrimSuffix(out, filepath.Ext(out))
	if err := writeStub(base+".h", []byte(hContent)); err != nil {
		return err
	}
	if err := writeStub(base+".c", []byte(cContent)); err != nil {
		return err
	}
	// The WIT directory. `wasm-tools component embed` resolves `deps/` only when
	// given a DIRECTORY, so the layout matters, not just the contents.
	return writeComponentWitDir(cfg, filepath.Join(filepath.Dir(base), "wit"))
}

// writeComponentWitDir lays out the WIT the consumer's build needs:
//
//	<dir>/consumer.wit                    a world importing our interface
//	<dir>/deps/regexped-<pkg>/<pkg>.wit   our interface, export world stripped
func writeComponentWitDir(cfg config.BuildConfig, dir string) error {
	// ONE derivation again: the package, the world, and which interfaces exist.
	pkg, world, funcs, sets, err := witParts(cfg)
	if err != nil {
		return err
	}
	witText := renderWit(cfg, pkg, world, funcs, sets)
	ver := ""
	if cfg.WitVersion != "" {
		ver = "@" + cfg.WitVersion
	}
	var importLines strings.Builder
	if len(funcs) > 0 {
		fmt.Fprintf(&importLines, "    import regexped:%s/matcher%s;\n", pkg, ver)
	}
	if len(sets) > 0 {
		fmt.Fprintf(&importLines, "    import regexped:%s/sets%s;\n", pkg, ver)
	}

	consumer := fmt.Sprintf(`// Auto-generated by regexped. Do not edit.
//
// The world the CONSUMER declares. Its own package, so it cannot collide with
// the interface package under deps/. Add your own exports to it — a component
// with no exports can be composed but not run.

package regexped-consumer:%s;

world %s {
%s}
`, pkg, consumerWorld(world), importLines.String())

	if err := writeStub(filepath.Join(dir, "consumer.wit"), []byte(consumer)); err != nil {
		return err
	}
	// A dependency package supplies the INTERFACE only: an exporting world in it
	// would describe a component rather than a dependency.
	depDir := filepath.Join(dir, "deps", "regexped-"+pkg)
	// One file for the whole package: it may define `matcher`, `sets`, or both,
	// and splitting them would buy nothing — WIT resolves a package from its
	// directory, not from file names. Named for the PACKAGE rather than for one
	// of the interfaces, since a sets-only config defines no `matcher` at all.
	return writeStub(filepath.Join(depDir, pkg+".wit"), []byte(stripExportWorld(witText)))
}

// stripExportWorld removes the `world … { export … }` block from generated WIT.
func stripExportWorld(witText string) string {
	return strings.TrimRight(strings.Join(dropWorld(witText), "\n"), "\n") + "\n"
}

// genCComponentStubFiles renders both halves.
func genCComponentStubFiles(cfg config.BuildConfig, hBasename string) (hContent, cContent string, err error) {
	// ONE derivation for everything the stub is built from — the package name,
	// the function names and the sets — through the same validation the WIT
	// itself goes through. Re-deriving any of it here would mean a second error
	// branch for a failure the first call has already ruled out.
	pkg, world, funcs, sets, err := witParts(cfg)
	if err != nil {
		return "", "", err
	}
	// The KEBAB name, not the snake_case one: a WASM import_name is the WIT
	// function name verbatim. Rust's macro does the kebab-to-snake mapping
	// itself, so the Rust stub wants the other form — using that here produced
	// "import interface … is missing function parse_url".
	names := kebabNames(funcs)
	importModule := "regexped:" + pkg + "/matcher"
	setsImportModule := "regexped:" + pkg + "/sets"
	if cfg.WitVersion != "" {
		importModule += "@" + cfg.WitVersion
		setsImportModule += "@" + cfg.WitVersion
	}

	var hb, cb strings.Builder
	var anyH bool
	var cparts []string
	needAlloc := false

	for _, re := range cfg.Regexps {
		// The HEADER comes from the module-format generator, unchanged: same API,
		// generated by the same code. Its .c half is discarded on purpose.
		h, _, groups, e := genCPartsForEntry(re, importModule)
		if e != nil {
			return "", "", e
		}
		if h == "" {
			continue
		}
		anyH = true
		hb.WriteString(h)

		if re.MatchFunc != "" {
			cparts = append(cparts, genCComponentMatch(importModule, re.MatchFunc, names[re.MatchFunc]))
		}
		if re.FindFunc != "" {
			cparts = append(cparts, genCComponentFind(importModule, re.FindFunc, names[re.FindFunc]))
		}
		if re.GroupsFunc != "" {
			// The group info comes BACK from genCPartsForEntry above: it parsed
			// this very pattern, so a second parse here could only fail where
			// that one already had.
			needAlloc = true
			cparts = append(cparts, genCComponentGroups(importModule, re.GroupsFunc, names[re.GroupsFunc], groups.num, groups.named))
		}
	}
	shapes := newSetShapes(cfg)
	setH, setC := genCComponentSetParts(cfg, sets, setsImportModule, shapes)
	if setH != "" {
		anyH = true
		hb.WriteString(setH)
		cparts = append(cparts, setC)
		// A set returns LISTS — ids from the `_all` pair, tuples from the find
		// resource — and the canonical ABI lowers a returned list into the
		// CALLER's memory through the caller's allocator. So any set capability
		// that returns one makes cabi_realloc mandatory, exactly as `groups`
		// does for a single pattern. Without it `component new` refuses with
		// "module does not export a function named cabi_realloc".
		for _, st := range cfg.Sets {
			if st.MatchAll != "" || st.ScanAll != "" || st.Find != "" {
				needAlloc = true
				break
			}
		}
	}
	if !anyH {
		return "", "", nil
	}

	header := cTypesPreamble(shapes.anyWantsCache())
	hContent = "/* Auto-generated by regexped. Do not edit.\n" +
		"   COMPONENT stub (wasm_format: component). The API below is identical to the\n" +
		"   module-format stub's, so switching formats changes no calling code.\n\n" +
		"   Build:\n" +
		"     clang --target=wasm32-wasi -nostdlib -DRX_SET_CACHE=0 -Wl,--no-entry -o core.wasm your.c " + strings.TrimSuffix(hBasename, ".h") + ".c\n" +
		"     wasm-tools component embed wit core.wasm --world " + consumerWorld(world) + " -o embedded.wasm\n" +
		"     wasm-tools component new embedded.wasm -o guest.wasm\n" +
		"     regexped merge --config=<config>.yaml --main=guest.wasm " + filepath.Base(cfg.WasmFile) + "\n\n" +
		"   The last step is the SAME `regexped merge` a module build runs: it\n" +
		"   dispatches on wasm_format and shells out to wac here, to wasm-merge\n" +
		"   there. The two wasm-tools steps above are yours, not regexped's —\n" +
		"   they wrap YOUR compiled code, and only the wasip1 target needs them\n" +
		"   (clang --target=wasm32-wasip2 emits a component directly).\n\n" +
		"   The `wit` directory beside this header is generated too, and\n" +
		"   `component embed` needs the DIRECTORY, not one file: it resolves deps/\n" +
		"   from it. */\n" +
		"#pragma once\n\n" + strings.TrimPrefix(header, "/* Auto-generated by regexped. Do not edit. */\n#pragma once\n\n") + hb.String()

	cb.WriteString("/* Auto-generated by regexped. Do not edit. */\n")
	fmt.Fprintf(&cb, "#include \"%s\"\n\n", hBasename)
	cb.WriteString(cComponentU32Reader)
	if needAlloc {
		cb.WriteString(cComponentAllocator())
	}
	for _, p := range cparts {
		cb.WriteString(p)
	}
	return hContent, cb.String(), nil
}

// cComponentAllocator emits the guest-side allocator the canonical ABI requires
// of anything that RECEIVES a list: the composition glue allocates the returned
// list in this component's memory by calling `cabi_realloc`.
//
// Three properties this has to get right, each learned from a failure:
//
//   - it is the COMPONENT'S allocator, not the stub's. The wasip1 adapter calls
//     it too (its `allocate_stack` does), so a heap sized for a group list alone
//     traps the moment the example is built as a command component.
//   - it therefore must NOT be reset globally. An earlier version zeroed the
//     bump pointer at the head of each groups call, which would hand out memory
//     the adapter was already using. The wrappers instead SAVE the mark before
//     their call and restore it after, rewinding only their own allocation.
//   - it is WEAK, so a program that already defines `cabi_realloc` — or links
//     something that does — wins. wit-bindgen's C output does the same.
func cComponentAllocator() string {
	return `/* Canonical-ABI allocator. A returned list lives in OUR memory, so the
   composition glue calls this to make room for it — and so does the wasip1
   adapter, if this component is built as a command. It is therefore the
   COMPONENT'S allocator, not this stub's private scratch: it is never reset
   wholesale. The generated wrappers save the mark before their call and restore
   it afterwards, which rewinds their own allocation and nothing else.

   WEAK, so your own cabi_realloc wins if you have one. */
#ifndef REGEXPED_CABI_REALLOC_DEFINED
#define REGEXPED_CABI_REALLOC_DEFINED

#ifndef REGEXPED_CABI_HEAP_BYTES
/* 256 KB. Sized by MEASUREMENT, not taste: the wasip1 adapter's allocate_stack
   takes the bulk of it when this component is built as a command, and 128 KB was
   observed to leave too little for a group list afterwards. A component with no
   adapter needs only 12 bytes per group and can define this much smaller; one
   that composes something hungrier can raise it. The allocator TRAPS rather than
   overrun, so a wrong value fails loudly. */
#define REGEXPED_CABI_HEAP_BYTES 262144
#endif

static unsigned char rx_cabi_heap[REGEXPED_CABI_HEAP_BYTES];
static unsigned rx_cabi_used = 0;

/* Save/restore the bump mark. Called by the generated wrappers, not by user
   code: only allocations made between the two calls are reclaimed.

   WEAK and shared BY NAME, like cabi_realloc itself. Two regexped C component
   stubs linked into one guest then keep ONE definition of each, which is what
   makes every wrapper save and restore the mark of the heap the winning
   cabi_realloc actually allocates from. Strong definitions failed the link as
   duplicates; per-stub names would have let one stub rewind a counter that
   allocator never advanced. */
__attribute__((__weak__)) unsigned regexped_cabi_mark(void) { return rx_cabi_used; }
__attribute__((__weak__)) void regexped_cabi_release(unsigned mark) { rx_cabi_used = mark; }

/* Byte by byte on purpose: there is no libc to supply memcpy, and optnone keeps
   the compiler from turning the loop back into a call to one. */
__attribute__((__noinline__, __optnone__))
static void rx_cabi_copy(unsigned char *dst, const unsigned char *src, unsigned n) {
    for (unsigned i = 0; i < n; i++) dst[i] = src[i];
}

__attribute__((__weak__, export_name("cabi_realloc")))
void *cabi_realloc(void *old_ptr, unsigned old_size, unsigned align, unsigned new_size) {
    unsigned p = (rx_cabi_used + align - 1) & ~(align - 1);
    if (p + new_size > sizeof rx_cabi_heap) {
        /* Out of scratch. Trapping is the only honest answer: returning a bad
           pointer would corrupt the caller's read of the list. Raise
           REGEXPED_CABI_HEAP_BYTES. */
        __builtin_trap();
    }
    rx_cabi_used = p + new_size;
    /* A REALLOC keeps what the block held, up to the smaller size. No regexped
       type ever grows a list, but this is the whole component's allocator and
       something else in it may. */
    if (old_ptr)
        rx_cabi_copy(&rx_cabi_heap[p], (const unsigned char *)old_ptr,
                     old_size < new_size ? old_size : new_size);
    return &rx_cabi_heap[p];
}
#endif

`
}

// cComponentU32Reader is emitted at the top of every component .c: the one way
// the bodies read a u32 out of a canonical-ABI result area or list.
const cComponentU32Reader = `/* A little-endian u32 read from a canonical-ABI result area or list. Reading
   the bytes rather than casting the pointer keeps it clear of C's aliasing and
   alignment rules; the compiler folds it to one load. */
static inline unsigned int rx_cabi_u32(const unsigned char *p) {
    return (unsigned int)p[0] | (unsigned int)p[1] << 8 |
           (unsigned int)p[2] << 16 | (unsigned int)p[3] << 24;
}

`

func genCComponentMatch(importModule, funcName, witFunc string) string {
	ffi := "ffi_" + funcName
	var sb strings.Builder
	// The anchored shape takes no `start`, so its lowered signature is one
	// argument shorter than the others.
	fmt.Fprintf(&sb, `__attribute__((__import_module__("%s"), __import_name__("%s")))
extern void %s(const unsigned char *ptr, unsigned int len, unsigned char *ret);

`, importModule, witFunc, ffi)
	fmt.Fprintf(&sb, `ptrdiff_t %s(const char *input, size_t len) {
    /* result<option<u32>, error-code>: @0 result disc, @4 option disc, @8 end */
    __attribute__((aligned(4))) unsigned char area[12] = {0};
    %s((const unsigned char *)input, (unsigned int)len, area);
    if (area[0] != 0) return RX_ERR_BT_OVERFLOW;   /* UNKNOWN, not "no match" */
    if (area[4] == 0) return -1;
    return (ptrdiff_t)rx_cabi_u32(area + 8);
}

`, funcName, ffi)
	return sb.String()
}

// cComponentIterInit is the `_init` and `_free` of a single-pattern find or
// groups iterator. The two shapes hold the same fields, start the same way and
// end the same way — only their `next` differs.
//
// The scan lives behind a RESOURCE here, so `_init` constructs one and `_free`
// drops it. scratch[0] carries the handle, and 0 means none: the canonical ABI
// never hands out handle 0. scratch[1] is unused. The struct is the MODULE
// format's, shared because the header is — a module iterator walks the input
// itself and leaves the scratch zero.
//
// `_init` WRITES the struct and never reads it. The contract is C's usual one:
// `_init` before `_next` or `_free`, and `_free` before initialising the same
// struct again. Anything that tried to tell a live iterator from a fresh one
// would have to read storage the caller may never have initialised.
//
// The handle is taken IN `_init`, not lazily on the first `next`. Laziness would
// save the input copy for an iterator that is built and never driven — which is
// what the Rust stub does — but it puts a CONSTRUCTOR call inside `next`, and
// the C set scanner, which is the shape known to work end to end, constructs in
// `_init` for the same reason. Matching it keeps one story for both resources.
func cComponentIterInit(module, kebab, funcName, iterType, ctor, drop string) string {
	return fmt.Sprintf(`__attribute__((__import_module__("%[3]s"), __import_name__("[constructor]%[4]s")))
extern int %[5]s(const unsigned char *ptr, unsigned int len, unsigned int start);

__attribute__((__import_module__("%[3]s"), __import_name__("[resource-drop]%[4]s")))
extern void %[6]s(int handle);

int %[1]s_init(%[2]s *iter, const char *input, size_t len, size_t offset) {
    if (!iter || !input) return RX_ERR_NULL_ARG;
    /* The interface is u32. */
    if (len > 0x7FFFFFFF || offset > 0x7FFFFFFF) return RX_ERR_RANGE;
    /* Writes only: a live iterator must be _free'd before it is initialised
       again, so nothing here reads what the struct held. */
    iter->input = input;
    iter->len = len;
    iter->offset = offset;
    iter->prev_end = (size_t)-1;
    iter->done = (offset > len);
    iter->scratch[0] = (unsigned)%[5]s((const unsigned char *)input,
                                       (unsigned int)len, (unsigned int)offset);
    iter->scratch[1] = 0;
    return 0;
}

void %[1]s_free(%[2]s *iter) {
    if (!iter) return;
    if (iter->scratch[0] != 0) %[6]s((int)iter->scratch[0]);
    /* The handle is cleared, so a second call does nothing rather than drop it
       twice. Only for a struct that went through _init. */
    iter->scratch[0] = 0;
    iter->done = 1;
}

`, funcName, iterType, module, kebab, ctor, drop)
}

func genCComponentFind(importModule, funcName, witFunc string) string {
	ffi := "ffi_" + funcName
	// ffi_<name>__res_*: a double underscore and a suffix no WIT name can
	// produce, so an export named like `<name>_next` cannot collide with the
	// resource's own imports — and no leading underscore, which C reserves at
	// file scope.
	ctor := "ffi_" + funcName + "__res_new"
	drop := "ffi_" + funcName + "__res_drop"
	iterType := cIterTypeName(funcName)
	var sb strings.Builder
	sb.WriteString(cComponentImportDecl(importModule, "[method]"+witFunc+".next", ffi,
		"int handle, unsigned char *ret"))
	sb.WriteString(cComponentIterInit(importModule, witFunc, funcName, iterType, ctor, drop))
	fmt.Fprintf(&sb, `int %[1]s_next(%[2]s *iter, rx_match_t *out_match) {
    if (!iter || !out_match) return RX_ERR_NULL_ARG;
    while (!iter->done) {
        /* result<option<tuple<u32,u32>>, error-code>:
           @0 result disc, @4 option disc, @8 start, @12 end.
           The scan lives inside the component and advances itself, so this
           passes only the handle — the input crossed once, at construction. */
        __attribute__((aligned(4))) unsigned char area[16] = {0};
        %[3]s((int)iter->scratch[0], area);
        if (area[0] != 0) { iter->done = 1; return RX_ERR_BT_OVERFLOW; }
        if (area[4] == 0) { iter->done = 1; return 0; }
        size_t start = (size_t)rx_cabi_u32(area + 8);
        size_t end   = (size_t)rx_cabi_u32(area + 12);
        /* Go's FindAllIndex rule: an EMPTY match beginning exactly where the
           previous REPORTED match ended is suppressed. The component has already
           advanced past it, so this only decides whether it is reported. */
        if (start == end && iter->prev_end == start) continue;
        iter->prev_end = end;
        /* Kept in step with the component's own position, so a caller reading
           it sees the module format's meaning: the next position to try. */
        iter->offset = (end > start) ? end : start + 1;
        out_match->start = (ptrdiff_t)start;
        out_match->end   = (ptrdiff_t)end;
        return 1;
    }
    return 0;
}

`, funcName, iterType, ffi)
	return sb.String()
}

func genCComponentGroups(importModule, funcName, witFunc string, numGroups int, namedGroups map[string]int) string {
	ffi := "ffi_" + funcName
	ctor := "ffi_" + funcName + "__res_new"
	drop := "ffi_" + funcName + "__res_drop"
	iterType := cIterTypeName(funcName)
	funcUpper := toUpperIdent(funcName)
	var sb strings.Builder
	sb.WriteString(cComponentImportDecl(importModule, "[method]"+witFunc+".next", ffi,
		"int handle, unsigned char *ret"))

	// The index-aligned name table and lookup are IDENTICAL to the module
	// format's, so they are generated by the same code path.
	sb.WriteString(cGroupsNameTable(funcName, numGroups, namedGroups))

	sb.WriteString(cComponentIterInit(importModule, witFunc, funcName, iterType, ctor, drop))
	fmt.Fprintf(&sb, `int %[1]s_next(%[2]s *iter, rx_group_t out_groups[static %[4]s_GROUPS]) {
    if (!iter || !out_groups) return RX_ERR_NULL_ARG;
    while (!iter->done) {
        /* result<list<option<tuple<u32,u32>>>, error-code>:
           @0 disc, @4 list ptr, @8 list len. Each element is 12 bytes:
           @0 option disc, @4 start, @8 end. An EMPTY list means finished. */
        __attribute__((aligned(4))) unsigned char area[12] = {0};
        /* The handle is taken BEFORE the mark, and that ordering is
           load-bearing. Constructing the scanner is a call whose effects
           OUTLIVE it — the composition glue allocates in this component's
           memory for it — so rewinding over it hands that memory back while it
           is still owned, and the next write through a stack pointer lands in
           reused bytes. Observed as the guest's own argv buffer going out of
           bounds two calls later. */
        int _h = (int)iter->scratch[0];
        /* Rewind only what THIS call allocates: cabi_realloc is the whole
           component's allocator, and a wholesale reset would hand out memory
           something else is still using. */
        unsigned _mark = regexped_cabi_mark();
        %[3]s(_h, area);
        if (area[0] != 0) { iter->done = 1; regexped_cabi_release(_mark); return RX_ERR_BT_OVERFLOW; }
        const unsigned char *elems = (const unsigned char *)(size_t)rx_cabi_u32(area + 4);
        unsigned int n = rx_cabi_u32(area + 8);
        if (!elems || n == 0) { iter->done = 1; regexped_cabi_release(_mark); return 0; }
        /* Group 0 is the whole match and is always set when the engine reported
           one; its extent drives the empty-match rule. */
        if (elems[0] == 0) { iter->done = 1; regexped_cabi_release(_mark); return 0; }
        size_t start = (size_t)rx_cabi_u32(elems + 4);
        size_t end   = (size_t)rx_cabi_u32(elems + 8);
        if (start == end && iter->prev_end == start) { regexped_cabi_release(_mark); continue; }
        iter->prev_end = end;
        iter->offset = (end > start) ? end : start + 1;
        for (unsigned int i = 0; i < %[4]s_GROUPS; i++) {
            if (i >= n) {
                /* Shorter list than the pattern's group count cannot happen, but
                   a caller's array must never be left uninitialised. */
                out_groups[i].start = -1;
                out_groups[i].end   = -1;
                continue;
            }
            const unsigned char *g = elems + (size_t)i * 12;
            if (g[0] == 0) {
                out_groups[i].start = -1;
                out_groups[i].end   = -1;
            } else {
                out_groups[i].start = (ptrdiff_t)rx_cabi_u32(g + 4);
                out_groups[i].end   = (ptrdiff_t)rx_cabi_u32(g + 8);
            }
        }
        /* The groups are copied into the CALLER's array, so the list is dead. */
        regexped_cabi_release(_mark);
        return 1;
    }
    return 0;
}

`, funcName, iterType, ffi, funcUpper)
	return sb.String()
}
